// Recursively extract string/bytes constants from marshaled code objects (py3.12).
import { readFileSync } from 'node:fs';

const file = process.argv[2];
const buf = readFileSync(file);
let q = 0;
const strings = [];
const refs = [];
function rb() { return buf[q++]; }
function rl() { const v = buf.readInt32LE(q); q += 4; return v; }
function rbytes(n) { const b = buf.subarray(q, q + n); q += n; return b; }

function parseObj() {
  let t = rb();
  const hasRef = (t & 0x80) !== 0;
  t &= 0x7f;
  const c = String.fromCharCode(t);
  const container = '()[]{}<>c'.includes(c);
  let refIdx = -1;
  if (hasRef && container) { refIdx = refs.length; refs.push(null); }
  let val;
  switch (c) {
    case 'c': {
      for (let i = 0; i < 5; i++) rl();
      parseObj(); parseObj(); parseObj(); parseObj(); parseObj();
      parseObj(); parseObj(); parseObj();
      rl();
      parseObj(); parseObj();
      val = null;
      break;
    }
    case '(': case ')': {
      const n = c === ')' ? rb() : rl();
      const a = [];
      for (let i = 0; i < n; i++) a.push(parseObj());
      val = a; break;
    }
    case '[': { const n = rl(); const a = []; for (let i = 0; i < n; i++) a.push(parseObj()); val = a; break; }
    case '<': case '>': { const n = rl(); const a = []; for (let i = 0; i < n; i++) a.push(parseObj()); val = a; break; }
    case '{': {
      const d = [];
      while (true) { const k = parseObj(); if (k === NULL_SENTINEL) break; d.push([k, parseObj()]); }
      val = d; break;
    }
    case 's': { const n = rl(); val = 'BYTES:' + rbytes(n).toString('latin1'); strings.push(val); break; }
    case 'u': { const n = rl(); val = rbytes(n).toString('utf8'); strings.push(val); break; }
    case 'a': case 'z': case 't': { const n = c === 't' ? rl() : rb(); val = rbytes(n).toString('utf8'); strings.push(val); break; }
    case 'A': case 'Z': { const n = c === 'A' ? rl() : rb(); val = rbytes(n).toString('utf8'); strings.push(val); break; }
    case 'i': return rl();
    case 'I': { const v = Number(buf.readBigInt64LE(q)); q += 8; return v; }
    case 'g': { const v = buf.readDoubleLE(q); q += 8; return v; }
    case 'x': case 'y': { q += 16; return null; }
    case 'l': { // long (PyLong) 3.12: sign byte then digits
      const n0 = rb(); const n = Math.abs(n0); let v = 0n;
      for (let i = 0; i < n; i++) { const d = buf.readUInt16LE(q); q += 2; v |= BigInt(d) << BigInt(15 * i); }
      return n0 < 0 ? -v : v; }
    case 'N': return null;
    case 'T': return true;
    case 'F': return false;
    case '.': return null;
    case '0': return NULL_SENTINEL;
    case 'r': { return refs[rl()]; }
    default: throw new Error('unknown type ' + c + ' (' + t + ') at ' + q);
  }
  if (hasRef) { if (refIdx >= 0) refs[refIdx] = val; else refs.push(val); }
  return val;
}
const NULL_SENTINEL = Symbol('null');
parseObj();
if (q !== buf.length) console.error('WARNING: stopped at', q, 'of', buf.length);
for (const s of strings) console.log(JSON.stringify(s));
